<p class="eyebrow">Catalogue management</p><div class="page-actions"><h1>Companies</h1><a class="button" href="<?= e(route('admin.companies.create')) ?>">Create company</a></div><form class="filters" method="get"><label>Search <input name="q" value="<?= e($filters['q']??'') ?>"></label><label>Status <select name="status"><option value="">All</option><?php foreach(['DRAFT','ACTIVE','SUSPENDED','ARCHIVED']as$s):?><option<?= ($filters['status']??'')===$s?' selected':'' ?>><?= $s ?></option><?php endforeach;?></select></label><button class="button button-small">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Company</th><th>Country Pack</th><th>Offering price</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($companies as $company):?><tr><td><b><?= e($company['display_name']) ?></b><br><small><?= e($company['ticker'].' · '.$company['stock_exchange']) ?></small></td><td><?= e($company['country_name']??'Unassigned') ?></td><td><?= e($company['share_price_minor']===null?'—':$company['share_price_minor'].' minor') ?></td><td><?= e($company['status']) ?></td><td><a href="<?= e(route('admin.companies.edit',['company'=>$company['id']])) ?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div>
